package com.bike.server.system;
import com.bike.server.common.ApiResponse;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/workstations") public class WorkstationController { private final WorkstationService service; public WorkstationController(WorkstationService service){this.service=service;} @GetMapping public ApiResponse<List<WorkstationView>> list(@RequestParam(required=false)String keyword){return ApiResponse.success("查询成功",service.list(keyword));} @PostMapping public ApiResponse<WorkstationView> create(@Valid @RequestBody WorkstationRequest request){return ApiResponse.success("创建成功",service.create(request));} @PutMapping("/{id}") public ApiResponse<WorkstationView> update(@PathVariable long id,@Valid @RequestBody WorkstationRequest request){return ApiResponse.success("更新成功",service.update(id,request));} @PutMapping("/{id}/status") public ApiResponse<WorkstationView> status(@PathVariable long id,@RequestParam boolean enabled){return ApiResponse.success("更新成功",service.updateStatus(id,enabled));} }
